SELECT setval('broker_order_id_seq', (SELECT MAX(id) FROM broker_order));
SELECT setval('trade_fill_id_seq', (SELECT MAX(id) FROM trade_fill));
SELECT setval('account_transaction_id_seq', (SELECT MAX(id) FROM account_transaction));
SELECT setval('user_preference_id_seq', (SELECT MAX(id) FROM user_preference));
